#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAXN = 100000;
const int MOD = 1000000007;

int n;
vector<int> g[MAXN + 1];
ll a[MAXN + 1], subsum[MAXN + 1];
int m = 0;

ll modexp(ll base, ll exp) {
    ll res = 1;
    while (exp) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return res;
}

ll fact[MAXN + 1], invfact[MAXN + 1];

void init_fact(int N) {
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = modexp(fact[N], MOD - 2);
    for (int i = N; i > 0; --i) invfact[i - 1] = invfact[i] * i % MOD;
}

ll C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
}

void dfs(int u, int fa) {
    subsum[u] = a[u];
    for (int v : g[u]) {
        if (v == fa) continue;
        dfs(v, u);
        subsum[u] += subsum[v];
    }
    if (fa != 0 && subsum[u] % 2 == 0) ++m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    for (int i = 1; i <= n; ++i) cin >> a[i];
    for (int i = 1; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    dfs(1, 0);
    if (subsum[1] % 2 == 1) {
        for (int k = 1; k < n; ++k) {
            cout << 0;
            if (k + 1 < n) cout << ' ';
        }
        return 0;
    }
    init_fact(n);
    for (int k = 1; k < n; ++k) {
        cout << C(m, k);
        if (k + 1 < n) cout << ' ';
    }
    return 0;
}
